const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

const reminderId = crypto.randomUUID();
const content = 'Follow up on delivery of order ORD-E0E671: Aurora Smart Desk Lamp Pro (x1) and CableCraft USB-C Organizer Strap 2-Pack (x2). Check shipping/tracking status.';
const creationTimestamp = new Date('2026-09-02T12:00:00').getTime() / 1000;  // now-ish context
const reminderTimestamp = new Date('2026-09-09T10:00:00').getTime() / 1000;  // 1 week later

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, '2026-09-02T12:00:00')
\`).run(reminderId, content, creationTimestamp, reminderTimestamp);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Reminder created:', JSON.stringify(reminder, null, 2));
"
